  async function previewSchedule(){
    capture();if(!canAuthor()||editor?.mode!=='periodic'||schedulePreviewPending)return;
    const fingerprint=scheduleFingerprint(),generation=epoch,serial=++schedulePreviewSerial;
    schedulePreview=null;schedulePreviewError='';schedulePreviewPending=true;paint();
    try{if(!callbacks.operationsCommand)throw new Error('일정 계산에 연결하지 못했습니다.');const result=await callbacks.operationsCommand({action:'schedule_preview',workflow_id:workflowId(),system_id:selection.system_id || '',definition:clone(editor)});
      if(generation!==epoch||serial!==schedulePreviewSerial||fingerprint!==scheduleFingerprint())return;
      if(result?.ok===false)throw new Error(result.error?.message || '일정 규칙을 확인해 주세요.');
      if(!Array.isArray(result?.preview)||result.preview.length!==2)throw new Error('다음 두 회차의 계산 결과를 확인하지 못했습니다.');
      schedulePreview={fingerprint,value:result.preview,warnings:result.warnings || []};
    }catch(reason){if(generation===epoch&&serial===schedulePreviewSerial&&fingerprint===scheduleFingerprint())schedulePreviewError=reason.message || '일정을 계산하지 못했습니다.';}
    finally{if(generation===epoch&&serial===schedulePreviewSerial){schedulePreviewPending=false;paint();}}
  }
