    if(before.content_hash!==after.content_hash||before.function!==after.function)changed.push('도구 코드');
    if(before.schema_hash!==after.schema_hash||JSON.stringify(item.input_schema)!==JSON.stringify(item.observed_input_schema))changed.push('입력 형식');
    if(JSON.stringify(item.output_schema)!==JSON.stringify(item.observed_output_schema))changed.push('결과 형식');
    if(before.config_hash!==after.config_hash)changed.push('연결 설정');
    if(before.environment!==after.environment)changed.push('실행 환경');
    if(before.tool_id!==after.tool_id)changed.push('연결 대상');
    return changed.length?`바뀐 항목: ${changed.join(' · ')}`:'입력·결과와 연결 내용은 같습니다. 도구 확인 정보를 다시 확인해 주세요.';
