  async function sharedAction(action,target){
    if(action==='shared_open'){sharedToolId=target.dataset.id;openTool(null);paint();return;}
    if(action==='shared_list'){sharedToolId='';paint();return;}
    if(action==='shared_native'){if(capability().is_admin)await callbacks.openNative?.('tools');return;}
    if(action==='pick_job_tool'){
      if(!canAuthor())return;const node=nodes(editor).find(item=>item.id===selectedNode);if(!node)return;
      const item=(target.dataset.shared?sharedTools():allTools()).find(item=>item.id===target.dataset.id);
      if(target.dataset.id&&!item)return;
      if(target.dataset.shared&&(item.state!=='available'||item.can_use===false))return;
      clearSharedGenerated(node);
      delete node.shared_tool_id;delete node.tool_reference;delete node.tool_contract_id;delete node.tool_contract_revision;
      if(item){node.mode='tool';if(target.dataset.shared){applySharedTool(node,item);}else{node.tool_contract_id=item.id;node.tool_contract_revision=item.revision;node.tool_reference=clone(item.reference);}}
      const picker=host?.querySelector?.('.ew-shared-picker');if(picker)picker.open=false;
      dirty=true;sharedPickerSearch='';stash();paint();host?.querySelector?.('.ew-shared-picker summary')?.focus();return;
    }
    if(!capability().is_admin)return;const item=sharedTools().find(item=>item.id===sharedToolId);if(!item)return;
    const restrictive=item.state==='unavailable'&&['shared_disable','shared_access'].includes(action);
    const payload={shared_tool_id:item.id,reference:restrictive?item.reference:item.observed_reference};
    if(action==='shared_review'||action==='shared_access'){
      const groups=(state.native_groups || []).filter(group=>!restrictive||(item.group_ids||[]).includes(group.id)),owners=state.people?.filter(item=>item.value.kind==='user').map(item=>({id:item.value.id,name:item.name||item.label})) || state.native_users || reviewers();
      const answer=await formDialog(action==='shared_review'?'입력·결과 확인':'쓸 수 있는 그룹·담당',`<p>${restrictive?'연결 장애 중에는 기존 그룹의 접근 권한을 줄이거나 모두 해제할 수 있습니다.':'그룹은 직접 선택해야 합니다.'} 개인 PAT를 입력하지 마세요.</p><div class="ew-shared-access"><fieldset><legend>쓸 수 있는 그룹</legend>${groups.map(group=>check('group:'+group.id,group.name||group.id,(item.group_ids||[]).includes(group.id))).join('')}</fieldset>${select('owner','담당',item.responsible_user_id||'',{'':'담당 선택',...optionList(owners)})}</div>${action==='shared_review'?`${sharedSchemaComparison(item)}${area('evidence','코드·시험·환경 확인 근거 (필수)','','minlength="8" maxlength="2000"')}`:''}`,'확인');
      if(!answer)return;payload.group_ids=groups.filter(group=>answer['group:'+group.id]).map(group=>group.id);payload.responsible_user_id=answer.owner;if(action==='shared_review')payload.evidence=answer.evidence;
    }else if(!await confirmDialog({title:action==='shared_disable'?'도구 사용을 중지할까요?':'도구를 다시 켤까요?',html:'<p>이 도구를 쓰는 모든 절차에 적용됩니다.</p>',confirmLabel:'확인'}))return;
    await command('shared_tool_'+action.slice(7),payload,{revision:item.revision,operations:true});
  }

