  function readDraft(){capture();return {definition:clone(editor),revision,dirty};}
  function reset(){summaryEdits.clear();sharedToolId='';sharedPickerSearch='';panelPositions.clear();paintedTarget='';stopAI();ruleNodeId='';validationCheckedAt='';schedulePreview=null;schedulePreviewError='';schedulePreviewPending=false;schedulePreviewSerial++;epoch++;readSerial++;writeSerial++;procedureSession++;procedureStarts.clear();procedureStart=false;procedureChoice='';procedureNames={};toolDrafts.clear();drafts.clear();requests.clear();privateComposers.clear();formBaselines.clear();state={};selection={};actor='';record=null;editor=null;revision=0;dirty=false;selectedNode='';tab='structure';factory='';toolId='';toolDraft=null;toolDirty=false;toolSchemaText='';toolSchemaError='';toolStart=false;toolChanging=false;toolSearch='';reviewerChanging=false;renderedToolSession=-1;toolAdvancedOpen=false;resources={skills:[],available:false};resourcesLoaded=false;resourcesLoading=false;resourcesError='';models=[];modelId='';modelLoaded=false;modelLoading=false;modelError='';prompt='';composerOpen=false;renderedComposerContext='';renderedComposerForced=false;busy=false;loading=false;error='';notice='';if(host)host.innerHTML='';reportStartContext();}
  return Object.freeze({render,handleEvent,reset,setBusy,syncHelpState,readDraft,canNavigate:()=>!busy&&!loading,canAuthor,load,command,propose,acceptProposal,readStartContext,closeStart});
